import { useState, useEffect } from 'react';
import { Navbar } from './components/layout/Navbar';
import { TabNav, TabType } from './components/layout/TabNav';
import { Footer } from './components/layout/Footer';
import { RecordPage } from './pages/RecordPage';
import { HistoryPage } from './pages/HistoryPage';
import { ReportPage } from './pages/ReportPage';
import { ToastContainer } from './components/common/ConfirmDialog';
import { ConfirmDialog } from './components/common/ConfirmDialog';
import { useTheme } from './hooks/useTheme';
import { useReviewStore } from './store/useReviewStore';
import { useConfigStore } from './store/useConfigStore';

function App() {
  const [activeTab, setActiveTab] = useState<TabType>('record');
  const { loadFromStorage: loadReviews } = useReviewStore();
  const { loadFromStorage: loadConfig } = useConfigStore();

  useTheme();
  useEffect(() => {
    loadReviews();
    loadConfig();
  }, []);

  const renderPage = () => {
    switch (activeTab) {
      case 'record':
        return <RecordPage />;
      case 'history':
        return <HistoryPage />;
      case 'report':
        return <ReportPage />;
      default:
        return <RecordPage />;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-900 flex flex-col transition-colors duration-200">
      <Navbar />

      <main className="flex-1 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-5 pt-6 pb-10 w-full">
        <TabNav activeTab={activeTab} onTabChange={setActiveTab} />

        <div className="tab-content active">
          {renderPage()}
        </div>
      </main>

      <Footer />

      <ToastContainer />
      <ConfirmDialog />
    </div>
  );
}

export default App;
