import { HeartPulse, Briefcase, BookOpen, Users, Wallet, Home, Brain, Coffee } from 'lucide-react';
import { DimensionConfig } from '../../types';

const ICON_MAP: Record<string, { icon: typeof HeartPulse; color: string }> = {
  'heart-pulse': { icon: HeartPulse, color: '#10B981' },
  'briefcase': { icon: Briefcase, color: '#3B82F6' },
  'book-open': { icon: BookOpen, color: '#F59E0B' },
  'users': { icon: Users, color: '#8B5CF6' },
  'wallet': { icon: Wallet, color: '#EC4899' },
  'home': { icon: Home, color: '#06B6D4' },
  'brain': { icon: Brain, color: '#6366F1' },
  'coffee': { icon: Coffee, color: '#F43F5E' },
};

interface DimensionCardProps {
  config: DimensionConfig;
  children: React.ReactNode;
}

export function DimensionCard({ config, children }: DimensionCardProps) {
  const iconInfo = ICON_MAP[config.icon] || ICON_MAP['brain'];
  const IconComponent = iconInfo.icon;

  return (
    <div
      className={`dimension-card ${config.bgClass} ${config.borderClass} ${config.darkBgClass} ${config.darkBorderClass}`}
    >
      <div className="flex items-center gap-3 mb-3">
        <div
          className="w-10 h-10 rounded-full flex items-center justify-center"
          style={{ backgroundColor: `${iconInfo.color}20` }}
        >
          <IconComponent className="w-5 h-5" style={{ color: iconInfo.color }} />
        </div>
        <div>
          <h3 className="font-medium text-slate-800 dark:text-slate-100">{config.name}</h3>
          <p className="text-xs text-slate-500 dark:text-slate-400">{config.subtitle}</p>
        </div>
      </div>
      {children}
    </div>
  );
}
