import { Calendar, TrendingUp, Target } from 'lucide-react';

interface StatsCardsProps {
  totalDays: number;
  currentStreak: number;
  completionRate: number;
}

export function StatsCards({ totalDays, currentStreak, completionRate }: StatsCardsProps) {
  const stats = [
    {
      label: '总复盘天数',
      value: totalDays,
      icon: <Calendar className="w-6 h-6" />,
      color: 'text-blue-600',
      bgColor: 'bg-blue-100 dark:bg-blue-900/30',
    },
    {
      label: '当前连续天数',
      value: currentStreak,
      icon: <TrendingUp className="w-6 h-6" />,
      color: 'text-green-600',
      bgColor: 'bg-green-100 dark:bg-green-900/30',
    },
    {
      label: '平均完成率',
      value: `${completionRate}%`,
      icon: <Target className="w-6 h-6" />,
      color: 'text-purple-600',
      bgColor: 'bg-purple-100 dark:bg-purple-900/30',
    },
  ];

  return (
    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 mb-6">
      {stats.map((stat, index) => (
        <div
          key={index}
          className="stat-card bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700"
        >
          <div className="flex items-center gap-3">
            <div className={`w-12 h-12 rounded-full ${stat.bgColor} flex items-center justify-center ${stat.color}`}>
              {stat.icon}
            </div>
            <div>
              <p className="text-sm text-slate-500 dark:text-slate-400">{stat.label}</p>
              <p className="text-2xl font-bold text-slate-800 dark:text-slate-100">{stat.value}</p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}
