import { create } from 'zustand';
import { ReviewRecord, ReviewContent } from '../types';
import { get as getStorage, setItem } from '../utils/storage';
import { STORAGE_KEYS } from '../constants/storage';
import { getToday } from '../utils/date';
import { v4 as uuidv4 } from 'uuid';

interface ReviewStore {
  reviews: ReviewRecord[];
  isLoading: boolean;
  isSyncing: boolean;
  todayRecord: ReviewRecord | null;
  getRecordByDate: (date: string) => ReviewRecord | null;
  getRecordsInRange: (start: string, end: string) => ReviewRecord[];
  saveRecord: (date: string, content: ReviewContent, summary: string) => void;
  updateRecord: (id: string, updates: Partial<ReviewRecord>) => void;
  deleteRecord: (id: string) => void;
  loadFromStorage: () => void;
}

export const useReviewStore = create<ReviewStore>((set, get) => ({
  reviews: [],
  isLoading: true,
  isSyncing: false,

  get todayRecord() {
    const today = getToday();
    return get().reviews.find(r => r.date === today) || null;
  },

  getRecordByDate: (date: string) => {
    return get().reviews.find(r => r.date === date) || null;
  },

  getRecordsInRange: (start: string, end: string) => {
    return get().reviews.filter(r => r.date >= start && r.date <= end);
  },

  saveRecord: (date: string, content: ReviewContent, summary: string) => {
    const existingIndex = get().reviews.findIndex(r => r.date === date);
    const now = new Date().toISOString();

    if (existingIndex >= 0) {
      const updated = { ...get().reviews[existingIndex], content, summary, updatedAt: now };
      const newReviews = [...get().reviews];
      newReviews[existingIndex] = updated;
      set({ reviews: newReviews });
      setItem(STORAGE_KEYS.REVIEW_DATA, newReviews);
    } else {
      const newRecord: ReviewRecord = {
        id: uuidv4(),
        date,
        content,
        summary,
        createdAt: now,
        updatedAt: now,
      };
      const newReviews = [newRecord, ...get().reviews];
      set({ reviews: newReviews });
      setItem(STORAGE_KEYS.REVIEW_DATA, newReviews);
    }
  },

  updateRecord: (id: string, updates: Partial<ReviewRecord>) => {
    const newReviews = get().reviews.map(r =>
      r.id === id ? { ...r, ...updates, updatedAt: new Date().toISOString() } : r
    );
    set({ reviews: newReviews });
    setItem(STORAGE_KEYS.REVIEW_DATA, newReviews);
  },

  deleteRecord: (id: string) => {
    const newReviews = get().reviews.filter(r => r.id !== id);
    set({ reviews: newReviews });
    setItem(STORAGE_KEYS.REVIEW_DATA, newReviews);
  },

  loadFromStorage: () => {
    const saved = getStorage<ReviewRecord[]>(STORAGE_KEYS.REVIEW_DATA);
    set({ reviews: saved || [], isLoading: false });
  },
}));
