import ReactECharts from 'echarts-for-react';
import { DIMENSIONS } from '../../constants/dimensions';

interface RadarChartProps {
  data: Record<string, number>;
}

export function RadarChart({ data }: RadarChartProps) {
  const indicator = Object.values(DIMENSIONS).map((d) => ({
    name: d.name,
    max: 100,
  }));

  const values = Object.keys(DIMENSIONS).map((key) => data[key] || 0);

  const option = {
    tooltip: {
      trigger: 'item',
    },
    radar: {
      indicator,
      shape: 'polygon',
      splitNumber: 4,
      axisName: {
        color: '#64748B',
      },
      splitLine: {
        lineStyle: {
          color: '#E2E8F0',
        },
      },
      splitArea: {
        show: false,
      },
      axisLine: {
        lineStyle: {
          color: '#E2E8F0',
        },
      },
    },
    series: [
      {
        type: 'radar',
        data: [
          {
            value: values,
            name: '完成度',
            areaStyle: {
              color: 'rgba(59, 130, 246, 0.2)',
            },
            lineStyle: {
              color: '#3B82F6',
            },
            itemStyle: {
              color: '#3B82F6',
            },
          },
        ],
      },
    ],
  };

  return (
    <div className="bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm p-4">
      <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 mb-4">维度均衡度</h3>
      <ReactECharts option={option} style={{ height: '350px' }} />
    </div>
  );
}
