import { useState, useEffect } from 'react';
import { AlertCircle } from 'lucide-react';
import { Modal } from './Modal';

interface ConfirmDialogOptions {
  title: string;
  message: string;
  confirmText?: string;
  cancelText?: string;
}

let confirmResolve: ((result: boolean) => void) | null = null;

export function showConfirmDialog({
  title,
  message,
  confirmText = '确定',
  cancelText = '取消',
}: ConfirmDialogOptions): Promise<boolean> {
  const event = new CustomEvent('show-confirm', {
    detail: { title, message, confirmText, cancelText },
  });
  window.dispatchEvent(event);

  return new Promise((resolve) => {
    confirmResolve = resolve;
  });
}

export function showToast(message: string, type: 'success' | 'error' | 'info' = 'success') {
  const event = new CustomEvent('show-toast', { detail: { message, type } });
  window.dispatchEvent(event);
}

export function ConfirmDialog() {
  const [isOpen, setIsOpen] = useState(false);
  const [config, setConfig] = useState<ConfirmDialogOptions>({
    title: '',
    message: '',
    confirmText: '确定',
    cancelText: '取消',
  });

  useEffect(() => {
    const handleShowConfirm = (e: CustomEvent<ConfirmDialogOptions>) => {
      setConfig(e.detail);
      setIsOpen(true);
    };

    window.addEventListener('show-confirm', handleShowConfirm as EventListener);
    return () => window.removeEventListener('show-confirm', handleShowConfirm as EventListener);
  }, []);

  const handleConfirm = () => {
    setIsOpen(false);
    confirmResolve?.(true);
    confirmResolve = null;
  };

  const handleCancel = () => {
    setIsOpen(false);
    confirmResolve?.(false);
    confirmResolve = null;
  };

  return (
    <Modal
      isOpen={isOpen}
      onClose={handleCancel}
      title={config.title}
      confirmText={config.confirmText}
      cancelText={config.cancelText}
      onConfirm={handleConfirm}
      icon={<AlertCircle className="w-8 h-8 text-blue-600 dark:text-blue-400" />}
    >
      {config.message}
    </Modal>
  );
}

export function ToastContainer() {
  const [toast, setToast] = useState<{ message: string; type: 'success' | 'error' | 'info' } | null>(null);

  useEffect(() => {
    const handleShowToast = (e: CustomEvent<{ message: string; type: 'success' | 'error' | 'info' }>) => {
      setToast(e.detail);
      setTimeout(() => setToast(null), 3000);
    };

    window.addEventListener('show-toast', handleShowToast as EventListener);
    return () => window.removeEventListener('show-toast', handleShowToast as EventListener);
  }, []);

  if (!toast) return null;

  const bgColors = {
    success: 'bg-green-600',
    error: 'bg-red-600',
    info: 'bg-blue-600',
  };

  return (
    <div className="fixed bottom-4 right-4 z-[9999] animate-slide-up">
      <div className={`px-4 py-3 rounded-lg shadow-lg text-white text-sm font-medium ${bgColors[toast.type]}`}>
        {toast.message}
      </div>
    </div>
  );
}
