import { useMemo } from 'react';
import { StatsCards } from '../components/report/StatsCards';
import { CompletionChart } from '../components/report/CompletionChart';
import { TrendChart } from '../components/report/TrendChart';
import { RadarChart } from '../components/report/RadarChart';
import { useReviewStore } from '../store/useReviewStore';
import { DIMENSIONS } from '../constants/dimensions';
import { getDateRange, getToday, formatDate } from '../utils/date';

export function ReportPage() {
  const { reviews } = useReviewStore();

  const stats = useMemo(() => {
    const totalDays = reviews.length;

    let currentStreak = 0;
    const sortedDates = [...reviews].map((r) => r.date).sort().reverse();
    const today = getToday();
    const yesterday = formatDate(
      new Date(new Date().setDate(new Date().getDate() - 1)).toISOString().split('T')[0]
    );

    if (sortedDates.includes(today)) {
      currentStreak = 1;
      let checkDate = today;
      while (sortedDates.includes(formatDate(new Date(new Date(checkDate).setDate(new Date(checkDate).getDate() - 1)).toISOString().split('T')[0]))) {
        currentStreak++;
        checkDate = formatDate(new Date(new Date(checkDate).setDate(new Date(checkDate).getDate() - 1)).toISOString().split('T')[0]);
      }
    } else if (sortedDates.includes(yesterday)) {
      currentStreak = 1;
      let checkDate = yesterday;
      while (sortedDates.includes(formatDate(new Date(new Date(checkDate).setDate(new Date(checkDate).getDate() - 1)).toISOString().split('T')[0]))) {
        currentStreak++;
        checkDate = formatDate(new Date(new Date(checkDate).setDate(new Date(checkDate).getDate() - 1)).toISOString().split('T')[0]);
      }
    }

    const { start, end } = getDateRange(30);
    const recentRecords = reviews.filter((r) => r.date >= start && r.date <= end);

    const completionRates: Record<string, number> = {};
    Object.keys(DIMENSIONS).forEach((key) => {
      const filled = recentRecords.filter((r) => {
        const content = r.content[key as keyof typeof r.content];
        return content && content.trim() !== '' && content !== '[]';
      }).length;
      completionRates[key] = recentRecords.length > 0 ? Math.round((filled / recentRecords.length) * 100) : 0;
    });

    const avgCompletion = Object.values(completionRates).reduce((a, b) => a + b, 0) / Object.keys(completionRates).length;

    return {
      totalDays,
      currentStreak,
      completionRate: Math.round(avgCompletion),
      completionRates,
    };
  }, [reviews]);

  const trendData = useMemo(() => {
    const { start, end } = getDateRange(7);
    const dates: string[] = [];
    const current = new Date(start);
    const endDate = new Date(end);

    while (current <= endDate) {
      dates.push(formatDate(current.toISOString().split('T')[0]));
      current.setDate(current.getDate() + 1);
    }

    return dates.map((date) => {
      const record = reviews.find((r) => r.date === date);
      const values: Record<string, number> = {};

      if (record) {
        Object.keys(DIMENSIONS).forEach((key) => {
          const content = record.content[key as keyof typeof record.content];
          values[key] = content && content.trim() !== '' && content !== '[]' ? 100 : 0;
        });
      } else {
        Object.keys(DIMENSIONS).forEach((key) => {
          values[key] = 0;
        });
      }

      return { date, values };
    });
  }, [reviews]);

  return (
    <div>
      <section className="mb-6">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-slate-100 mb-2">数据报告</h1>
        <p className="text-sm text-slate-500 dark:text-slate-400">洞察你的成长轨迹</p>
      </section>

      <StatsCards
        totalDays={stats.totalDays}
        currentStreak={stats.currentStreak}
        completionRate={stats.completionRate}
      />

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        <CompletionChart data={stats.completionRates} />
        <RadarChart data={stats.completionRates} />
      </div>

      <TrendChart data={trendData} />
    </div>
  );
}
