import { ReviewRecord } from '../../types';
import { HistoryItem } from './HistoryItem';

interface HistoryListProps {
  records: ReviewRecord[];
  searchQuery: string;
  onDelete: (id: string) => void;
}

export function HistoryList({ records, searchQuery, onDelete }: HistoryListProps) {
  const filteredRecords = records.filter((record) => {
    if (!searchQuery) return true;
    const query = searchQuery.toLowerCase();
    return (
      record.date.includes(query) ||
      record.summary.toLowerCase().includes(query) ||
      Object.values(record.content).some((value) =>
        value.toLowerCase().includes(query)
      )
    );
  });

  if (filteredRecords.length === 0) {
    return (
      <div className="text-center py-12 text-slate-500 dark:text-slate-400">
        {searchQuery ? '没有找到匹配的复盘记录' : '暂无复盘记录'}
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {filteredRecords.map((record) => (
        <HistoryItem key={record.id} record={record} onDelete={onDelete} />
      ))}
    </div>
  );
}
