import { useState, useEffect } from 'react';
import { HealthItem } from '../../types';
import { HEALTH_DEFAULTS } from '../../constants/dimensions';

interface HealthItemsEditorProps {
  value: HealthItem[];
  onChange: (items: HealthItem[]) => void;
}

export function HealthItemsEditor({ value, onChange }: HealthItemsEditorProps) {
  const [items, setItems] = useState<HealthItem[]>(HEALTH_DEFAULTS);

  useEffect(() => {
    if (value && value.length > 0) {
      setItems(value);
    } else {
      setItems(HEALTH_DEFAULTS);
    }
  }, [value]);

  const handleLabelChange = (index: number, label: string) => {
    const newItems = [...items];
    newItems[index] = { ...newItems[index], label };
    setItems(newItems);
    onChange(newItems);
  };

  const handleValueChange = (index: number, value: string) => {
    const newItems = [...items];
    newItems[index] = { ...newItems[index], value };
    setItems(newItems);
    onChange(newItems);
  };

  const handleAdd = (afterIndex: number) => {
    const newItems = [...items];
    newItems.splice(afterIndex + 1, 0, { label: '', value: '', placeholder: '填写内容' });
    setItems(newItems);
    onChange(newItems);
  };

  const handleRemove = (index: number) => {
    if (items.length <= 1) return;
    const newItems = items.filter((_, i) => i !== index);
    setItems(newItems);
    onChange(newItems);
  };

  return (
    <div className="space-y-1.5">
      {items.map((item, index) => (
        <div key={index} className="group flex items-center gap-1.5">
          <div className="flex opacity-0 group-hover:opacity-100 transition-opacity duration-150">
            <button
              type="button"
              onClick={() => handleRemove(index)}
              className="p-0.5 text-red-400 hover:text-red-600 cursor-pointer text-lg leading-none"
              title="删除"
            >
              ×
            </button>
            <button
              type="button"
              onClick={() => handleAdd(index)}
              className="p-0.5 text-green-400 hover:text-green-600 cursor-pointer text-lg leading-none"
              title="在此后添加"
            >
              +
            </button>
          </div>
          <input
            type="text"
            value={item.label}
            onChange={(e) => handleLabelChange(index, e.target.value)}
            placeholder="项目名"
            className="w-22 px-2 py-1.5 text-sm border border-green-200 dark:border-green-700 rounded-lg
              bg-green-50 dark:bg-green-900/30 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-green-500"
          />
          <span className="text-green-500 flex-shrink-0">:</span>
          <input
            type="text"
            value={item.value}
            onChange={(e) => handleValueChange(index, e.target.value)}
            placeholder={item.placeholder || '填写内容'}
            className="flex-1 px-2 py-1.5 text-sm border border-green-200 dark:border-green-700 rounded-lg
              bg-green-50 dark:bg-green-900/30 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-green-500"
          />
        </div>
      ))}
    </div>
  );
}
