import { create } from 'zustand';
import { UserConfig } from '../types';
import { get as getStorage, setItem } from '../utils/storage';
import { STORAGE_KEYS } from '../constants/storage';

interface ConfigStore extends UserConfig {
  setTheme: (theme: 'light' | 'dark' | 'auto') => void;
  toggleTheme: () => void;
  setReminder: (enabled: boolean, time?: string) => void;
  loadFromStorage: () => void;
}

export const useConfigStore = create<ConfigStore>((set, get) => ({
  theme: 'auto',
  reminderEnabled: false,
  reminderTime: '21:00',
  syncEnabled: false,

  setTheme: (theme) => {
    set({ theme });
    setItem(STORAGE_KEYS.USER_CONFIG, {
      theme,
      reminderEnabled: get().reminderEnabled,
      reminderTime: get().reminderTime,
      syncEnabled: get().syncEnabled,
    });
  },

  toggleTheme: () => {
    const current = get().theme;
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (current === 'light') {
      set({ theme: 'dark' });
    } else if (current === 'dark') {
      set({ theme: 'auto' });
    } else {
      set({ theme: prefersDark ? 'dark' : 'light' });
    }
  },

  setReminder: (enabled, time) => {
    set({
      reminderEnabled: enabled,
      reminderTime: time || get().reminderTime,
    });
    setItem(STORAGE_KEYS.USER_CONFIG, {
      theme: get().theme,
      reminderEnabled: enabled,
      reminderTime: time || get().reminderTime,
      syncEnabled: get().syncEnabled,
    });
  },

  loadFromStorage: () => {
    const saved = getStorage<UserConfig>(STORAGE_KEYS.USER_CONFIG);
    if (saved) {
      set(saved);
    }
  },
}));
