import ReactECharts from 'echarts-for-react';
import { DIMENSIONS } from '../../constants/dimensions';

interface CompletionChartProps {
  data: Record<string, number>;
}

export function CompletionChart({ data }: CompletionChartProps) {
  const option = {
    tooltip: {
      trigger: 'axis',
      axisPointer: {
        type: 'shadow',
      },
    },
    grid: {
      left: '3%',
      right: '4%',
      bottom: '3%',
      containLabel: true,
    },
    xAxis: {
      type: 'category',
      data: Object.values(DIMENSIONS).map((d) => d.name),
      axisLabel: {
        rotate: 45,
        fontSize: 11,
      },
    },
    yAxis: {
      type: 'value',
      max: 100,
      axisLabel: {
        formatter: '{value}%',
      },
    },
    series: [
      {
        name: '填写率',
        type: 'bar',
        data: Object.keys(DIMENSIONS).map((key) => ({
          value: data[key] || 0,
          itemStyle: {
            color: DIMENSIONS[key].color,
          },
        })),
        barWidth: '50%',
      },
    ],
  };

  return (
    <div className="bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm p-4">
      <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 mb-4">各维度填写率</h3>
      <ReactECharts option={option} style={{ height: '300px' }} />
    </div>
  );
}
