import ReactECharts from 'echarts-for-react';
import { DIMENSIONS } from '../../constants/dimensions';

interface TrendChartProps {
  data: Array<{ date: string; values: Record<string, number> }>;
}

export function TrendChart({ data }: TrendChartProps) {
  const option = {
    tooltip: {
      trigger: 'axis',
    },
    legend: {
      data: Object.values(DIMENSIONS).map((d) => d.name),
      top: 0,
      type: 'scroll',
    },
    grid: {
      left: '3%',
      right: '4%',
      bottom: '10%',
      containLabel: true,
    },
    xAxis: {
      type: 'category',
      data: data.map((d) => d.date),
      boundaryGap: false,
    },
    yAxis: {
      type: 'value',
      max: 100,
      axisLabel: {
        formatter: '{value}%',
      },
    },
    series: Object.keys(DIMENSIONS).map((key) => ({
      name: DIMENSIONS[key].name,
      type: 'line',
      data: data.map((d) => d.values[key] || 0),
      smooth: true,
      lineStyle: {
        width: 2,
      },
      itemStyle: {
        color: DIMENSIONS[key].color,
      },
    })),
  };

  return (
    <div className="bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm p-4">
      <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 mb-4">趋势图</h3>
      <ReactECharts option={option} style={{ height: '350px' }} />
    </div>
  );
}
