import { useState } from 'react';
import { ChevronDown, ChevronUp, Trash2, Edit2 } from 'lucide-react';
import { ReviewRecord } from '../../types';
import { formatDate } from '../../utils/date';
import { DIMENSIONS } from '../../constants/dimensions';

interface HistoryItemProps {
  record: ReviewRecord;
  onDelete: (id: string) => void;
}

export function HistoryItem({ record, onDelete }: HistoryItemProps) {
  const [isExpanded, setIsExpanded] = useState(false);

  const parseHealthContent = (healthStr: string) => {
    if (!healthStr) return [];
    try {
      const parsed = JSON.parse(healthStr);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  };

  return (
    <div className="bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm overflow-hidden">
      <div
        className="flex items-center justify-between p-4 cursor-pointer hover:bg-slate-50 dark:hover:bg-slate-700/50 transition-colors"
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div>
          <h3 className="font-medium text-slate-800 dark:text-slate-100">
            {formatDate(record.date, 'YYYY年MM月DD日')}
          </h3>
          <p className="text-sm text-slate-500 dark:text-slate-400">
            {formatDate(record.date, 'dddd')}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={(e) => {
              e.stopPropagation();
            }}
            className="p-2 text-slate-400 hover:text-blue-600 dark:hover:text-blue-400"
          >
            <Edit2 className="w-4 h-4" />
          </button>
          <button
            onClick={(e) => {
              e.stopPropagation();
              onDelete(record.id);
            }}
            className="p-2 text-slate-400 hover:text-red-600 dark:hover:text-red-400"
          >
            <Trash2 className="w-4 h-4" />
          </button>
          {isExpanded ? (
            <ChevronUp className="w-5 h-5 text-slate-400" />
          ) : (
            <ChevronDown className="w-5 h-5 text-slate-400" />
          )}
        </div>
      </div>

      {isExpanded && (
        <div className="px-4 pb-4 border-t border-slate-200 dark:border-slate-700">
          <div className="mt-4 space-y-4">
            {Object.entries(DIMENSIONS).map(([key, config]) => {
              const content =
                key === 'health'
                  ? parseHealthContent(record.content.health)
                  : record.content[key as keyof typeof record.content];

              if (key === 'health') {
                const healthItems = content as Array<{ label: string; value: string }>;
                if (healthItems.length === 0) return null;
                return (
                  <div key={key}>
                    <h4 className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-2">
                      {config.name}
                    </h4>
                    <div className="text-sm text-slate-600 dark:text-slate-400 space-y-1">
                      {healthItems.map((item, i) => (
                        <div key={i}>
                          {item.label}: {item.value || '(未填写)'}
                        </div>
                      ))}
                    </div>
                  </div>
                );
              }

              if (!content || (typeof content === 'string' && !content.trim())) return null;

              return (
                <div key={key}>
                  <h4 className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                    {config.name}
                  </h4>
                  <p className="text-sm text-slate-600 dark:text-slate-400 whitespace-pre-wrap">
                    {content as string}
                  </p>
                </div>
              );
            })}

            {record.summary && (
              <div>
                <h4 className="text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                  今日总结
                </h4>
                <p className="text-sm text-slate-600 dark:text-slate-400 whitespace-pre-wrap">
                  {record.summary}
                </p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
