import { Pencil, History, BarChart2 } from 'lucide-react';

export type TabType = 'record' | 'history' | 'report';

interface TabNavProps {
  activeTab: TabType;
  onTabChange: (tab: TabType) => void;
}

export function TabNav({ activeTab, onTabChange }: TabNavProps) {
  const tabs: { key: TabType; label: string; icon: React.ReactNode }[] = [
    { key: 'record', label: '记录', icon: <Pencil className="w-4 h-4" /> },
    { key: 'history', label: '历史', icon: <History className="w-4 h-4" /> },
    { key: 'report', label: '报告', icon: <BarChart2 className="w-4 h-4" /> },
  ];

  return (
    <div className="bg-white dark:bg-slate-800 rounded-lg border border-slate-200 dark:border-slate-700 shadow-sm mb-6">
      <div className="flex border-b border-slate-200 dark:border-slate-700">
        {tabs.map((tab) => (
          <button
            key={tab.key}
            onClick={() => onTabChange(tab.key)}
            className={`tab-btn ${activeTab === tab.key ? 'active' : 'text-slate-500 dark:text-slate-400 hover:text-slate-700 dark:hover:text-slate-200'}`}
          >
            <span className="inline-block mr-2">{tab.icon}</span>
            {tab.label}
          </button>
        ))}
      </div>
    </div>
  );
}
