import { useState } from 'react';
import { Button } from '../common/Button';
import { Save, RotateCcw } from 'lucide-react';
import { showConfirmDialog, showToast } from '../common/ConfirmDialog';
import { useReviewStore } from '../../store/useReviewStore';
import { ReviewContent } from '../../types';

interface SaveButtonProps {
  date: string;
  content: ReviewContent;
  summary: string;
  onSave: () => void;
  onReset: () => void;
}

export function SaveButton({ date, content, summary, onSave, onReset }: SaveButtonProps) {
  const [isSaving, setIsSaving] = useState(false);
  const { saveRecord } = useReviewStore();

  const handleSave = async () => {
    setIsSaving(true);
    try {
      saveRecord(date, content, summary);
      showToast('保存成功', 'success');
      onSave();
    } catch {
      showToast('保存失败', 'error');
    } finally {
      setIsSaving(false);
    }
  };

  const handleReset = async () => {
    const confirmed = await showConfirmDialog({
      title: '确认重置',
      message: '确定要重置今日复盘内容吗？',
    });
    if (confirmed) {
      onReset();
    }
  };

  return (
    <div className="flex gap-3 mt-6">
      <Button onClick={handleSave} disabled={isSaving} className="flex-1">
        <Save className="w-4 h-4 mr-2" />
        {isSaving ? '保存中...' : '保存'}
      </Button>
      <Button variant="secondary" onClick={handleReset}>
        <RotateCcw className="w-4 h-4 mr-2" />
        重置
      </Button>
    </div>
  );
}
