import { useState } from 'react';
import { Button } from './Button';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
  showCancel?: boolean;
  onConfirm?: () => void;
  confirmText?: string;
  cancelText?: string;
  icon?: React.ReactNode;
}

export function Modal({
  isOpen,
  onClose,
  title,
  children,
  showCancel = true,
  onConfirm,
  confirmText = '确定',
  cancelText = '取消',
  icon,
}: ModalProps) {
  const [shouldRender, setShouldRender] = useState(false);

  if (isOpen && !shouldRender) {
    setShouldRender(true);
  }

  if (!shouldRender) return null;

  return (
    <div
      className={`fixed inset-0 z-50 flex items-center justify-center transition-opacity duration-200 ${isOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}
      onClick={onClose}
    >
      <div className="absolute inset-0 bg-black/50" />
      <div
        className={`relative bg-white dark:bg-slate-800 rounded-xl shadow-xl p-6 w-full max-w-sm mx-4 transform transition-transform duration-200 ${isOpen ? 'scale-100' : 'scale-95'}`}
        onClick={(e) => e.stopPropagation()}
      >
        {icon && (
          <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-blue-100 flex items-center justify-center">
            {icon}
          </div>
        )}
        <h3 className="text-lg font-semibold text-slate-800 dark:text-slate-100 text-center mb-2">
          {title}
        </h3>
        <div className="text-sm text-slate-600 dark:text-slate-400 text-center mb-6">
          {children}
        </div>
        <div className="flex gap-3">
          {onConfirm && (
            <Button variant="primary" onClick={onConfirm} className="flex-1">
              {confirmText}
            </Button>
          )}
          {showCancel && (
            <Button variant="secondary" onClick={onClose} className="flex-1">
              {cancelText}
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}
