import { useState, useEffect } from 'react';
import { DimensionCard } from '../components/record/DimensionCard';
import { HealthItemsEditor } from '../components/record/HealthItemsEditor';
import { SummarySection } from '../components/record/SummarySection';
import { SaveButton } from '../components/record/SaveButton';
import { Textarea } from '../components/common/Textarea';
import { DIMENSIONS } from '../constants/dimensions';
import { HEALTH_DEFAULTS } from '../constants/dimensions';
import { useReviewStore } from '../store/useReviewStore';
import { getToday } from '../utils/date';
import { ReviewContent, HealthItem } from '../types';

export function RecordPage() {
  const { todayRecord, loadFromStorage } = useReviewStore();
  const [healthItems, setHealthItems] = useState<HealthItem[]>(HEALTH_DEFAULTS);
  const [content, setContent] = useState<ReviewContent>({
    health: '',
    work: '',
    study: '',
    social: '',
    finance: '',
    life: '',
    spirit: '',
    leisure: '',
  });
  const [summary, setSummary] = useState('');

  useEffect(() => {
    loadFromStorage();
  }, []);

  useEffect(() => {
    if (todayRecord) {
      setContent(todayRecord.content);
      setSummary(todayRecord.summary);
      if (todayRecord.content.health) {
        try {
          const parsed = JSON.parse(todayRecord.content.health);
          if (Array.isArray(parsed) && parsed.length > 0) {
            setHealthItems(parsed);
          }
        } catch {
          setHealthItems(HEALTH_DEFAULTS);
        }
      }
    }
  }, [todayRecord]);

  const handleHealthChange = (items: HealthItem[]) => {
    setHealthItems(items);
    setContent((prev) => ({
      ...prev,
      health: JSON.stringify(items),
    }));
  };

  const handleContentChange = (key: keyof ReviewContent, value: string) => {
    setContent((prev) => ({
      ...prev,
      [key]: value,
    }));
  };

  const handleReset = () => {
    setHealthItems(HEALTH_DEFAULTS);
    setContent({
      health: '',
      work: '',
      study: '',
      social: '',
      finance: '',
      life: '',
      spirit: '',
      leisure: '',
    });
    setSummary('');
  };

  const today = getToday();

  return (
    <div>
      <section className="mb-6">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-slate-100 mb-2">个人复盘</h1>
        <p className="text-sm text-slate-500 dark:text-slate-400">记录每一天的成长与反思</p>
      </section>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
        {Object.values(DIMENSIONS).map((config) => {
          if (config.key === 'health') {
            return (
              <DimensionCard key={config.key} config={config}>
                <HealthItemsEditor value={healthItems} onChange={handleHealthChange} />
              </DimensionCard>
            );
          }

          return (
            <DimensionCard key={config.key} config={config}>
              <Textarea
                value={content[config.key]}
                onChange={(e) => handleContentChange(config.key, e.target.value)}
                rows={3}
                placeholder={`记录今天的${config.name.toLowerCase()}...`}
              />
            </DimensionCard>
          );
        })}
      </div>

      <SummarySection value={summary} onChange={setSummary} />

      <SaveButton
        date={today}
        content={content}
        summary={summary}
        onSave={() => {}}
        onReset={handleReset}
      />
    </div>
  );
}
