import { useState } from 'react';
import { HistoryFilters } from '../components/history/HistoryFilters';
import { HistoryList } from '../components/history/HistoryList';
import { useReviewStore } from '../store/useReviewStore';
import { showConfirmDialog, showToast } from '../components/common/ConfirmDialog';

export function HistoryPage() {
  const { reviews, deleteRecord } = useReviewStore();
  const [searchQuery, setSearchQuery] = useState('');
  const [dateRange, setDateRange] = useState({ start: '2000-01-01', end: '2099-12-31' });

  const handleSearchChange = (query: string) => {
    setSearchQuery(query);
  };

  const handleDateChange = (start: string, end: string) => {
    setDateRange({ start, end });
  };

  const handleDelete = async (id: string) => {
    const confirmed = await showConfirmDialog({
      title: '确认删除',
      message: '确定要删除这条复盘记录吗？此操作不可撤销。',
      confirmText: '删除',
    });

    if (confirmed) {
      deleteRecord(id);
      showToast('删除成功', 'success');
    }
  };

  const filteredRecords = reviews.filter(
    (record) => record.date >= dateRange.start && record.date <= dateRange.end
  );

  return (
    <div>
      <section className="mb-6">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-slate-100 mb-2">历史记录</h1>
        <p className="text-sm text-slate-500 dark:text-slate-400">回顾过去的复盘历程</p>
      </section>

      <HistoryFilters onSearchChange={handleSearchChange} onDateChange={handleDateChange} />

      <HistoryList records={filteredRecords} searchQuery={searchQuery} onDelete={handleDelete} />
    </div>
  );
}
